// Service worker for one Learning Hub app (generated by tools/build.py; do not edit the copy in dist/).
// Every app on vardhangs.github.io shares one Cache Storage, so this worker only ever deletes caches whose
// names start with its own app id.
const APP_ID = "contest4";
const CACHE = "contest4-79d149efae";
const ASSETS = [
  "./",
  "./index.html",
  "./manifest.json",
  "./core/styles.css",
  "./config.js",
  "./core/sound.js",
  "./core/speech.js",
  "./data/voice-clips.js",
  "./core/voice.js",
  "./core/cloud.js",
  "./core/U.js",
  "./core/engine/fig.js",
  "./core/engine/alg.js",
  "./core/modes/contest.js",
  "./data/pzkit.js",
  "./data/pz4.js",
  "./data/videos.js",
  "./core/app.js",
  "./icons/icon-180.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/katex.min.js",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/katex.min.css",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_AMS-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Caligraphic-Bold.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Caligraphic-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Fraktur-Bold.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Fraktur-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Main-Bold.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Main-BoldItalic.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Main-Italic.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Main-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Math-BoldItalic.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Math-Italic.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_SansSerif-Bold.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_SansSerif-Italic.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_SansSerif-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Script-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Size1-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Size2-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Size3-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Size4-Regular.woff2",
  "https://cdn.jsdelivr.net/npm/katex@0.18.11/dist/fonts/KaTeX_Typewriter-Regular.woff2"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith(APP_ID + "-") && k !== CACHE).map((k) => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

// Network-first: always try the latest; fall back to the cache only when offline.
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  // Let the browser stream videos directly (range requests); don't cache them.
  if (url.pathname.includes("/videos/") && url.pathname.endsWith(".mp4")) return;
  // Only this app's own files and the pinned KaTeX files; never Firebase traffic.
  const mine = url.origin === self.location.origin && url.pathname.startsWith(new URL("./", self.location).pathname);
  const katex = url.origin === "https://cdn.jsdelivr.net" && url.pathname.startsWith("/npm/katex@");
  if (!mine && !katex) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)).catch(() => {}); }
        return res;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
